parameters.inputSchema:
{
   "title": "IntentRouter",
  "type": "object",
  "properties": {
    "intent": {
      "type": "string",
      "enum": ["full_plan", "hotel_only", "flight_only", "activity_only"],
      "description": "The classified intent of the user message"
    },
    "error": {
      "type": "boolean",
      "default": false,
      "description": "Return true if any of source, destination, travel_date, duration_days are missing or empty"
    },
    "error_msg": {
      "type": "string",
      "default": "",
      "description": "Friendly message listing which fields are missing"
    },
    "details": {
      "type": "object",
      "properties": {
        "source": {
          "type": "string",
          "description": "Departure city. Leave empty string if not mentioned by user"
        },
        "destination": {
          "type": "string",
          "description": "Destination city. Leave empty string if not mentioned by user"
        },
        "travel_date": {
          "type": "string",
          "description": "Date of travel. Leave empty string if not mentioned by user"
        },
        "duration_days": {
          "type": "number",
          "description": "Number of days for the trip. Set 0 if not mentioned by user"
        }
      }
    }
  },
  "required": ["intent", "error", "details"]
}
